-- Record of the Brkthru Floodlight fix in GTM-NTGC6X38 (2026-11-24). Safe to run twice.
insert into public.stream_events (owner, station, summary, keywords, status, context_link)
select 'logan','bcps','Ruth Johnson asked (Nov 24) to publish Brkthru''s Magnet Floodlight pixels today. Review of the Default Workspace (Brkthru built there, not in "Magnet - Brkthru"): 5 tags, 4 triggers, 3 variables added, no custom code, no live item touched. Fixed via one-time function bcps-gtm-magnet-fix-once (Sean approved): all 5 tags renamed "MAGNET | ...", Floodlight base tag moved off Initialization - All Pages to a new trigger limited to /bcps-departments/academics/magnet-programs. Review now: naming, untouched, up_to_date PASS. Scope check still flags 4 tags only because it cannot read escaped-hyphen regex (verified by hand: all path-limited). Not published; Sean publishes. Open: Apply Now trigger matches browardschoolscom.finalsite.com/...school-choice123, confirm in Preview.',
 array['bcps','gtm','governance','magnet','brkthru','vendor-access'],'completed','https://github.com/lesaruss/bcpsmarcomm/tree/claude/ruth-activation-next-steps-udhw7a'
where not exists (select 1 from public.stream_events where summary like 'Ruth Johnson asked (Nov 24) to publish Brkthru%');

insert into public.stream_events (owner, station, summary, keywords, status, context_link)
select 'logan','bcps','Brkthru Magnet Floodlight pixels PUBLISHED live as container version 6 of GTM-NTGC6X38 (Sean gave permission Nov 24). Before publishing: Apply Now trigger matched a finalsite.com staging address; corrected to /bcps-departments/school-choice123 (the live link). Verified: gtm.js served by Google contains DC-18130941 and the corrected match. 5 MAGNET | tags, base tag limited to magnet-programs pages, no existing tag changed. Brkthru access still closes Jan 15 2027. Open: reply to Ruth; Open House trigger (AudioEye aria-describedby + strong a) untested; fix review check to read escaped-hyphen regex.',
 array['bcps','gtm','governance','magnet','brkthru','published'],'completed','https://github.com/lesaruss/bcpsmarcomm/tree/claude/ruth-activation-next-steps-udhw7a'
where not exists (select 1 from public.stream_events where summary like 'Brkthru Magnet Floodlight pixels PUBLISHED live%');
